s && node tests/client-util.smoke.mjs && node tests/origin.smoke.mjs && node tests/catalog-source.smoke.mjs && node tests/backup.smoke.mjs && node tests/client-registration.e2e.mjs && node tests/claims.e2e.mjs && node tests/gateway-path.e2e.mjs && node tests/host-gateway.e2e.mjs\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/typert.host.js\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/2768651338/dsh-plugin-manager.git\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/cordis-plugin-group\": \"1.0.5\",\n    \"@deepseek-ai/cordis-plugin-include\": \"1.0.10\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"1.0.6\",\n    \"@deepseek-ai/dsh-api-gateway\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-api-remote-access\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-app-boot\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-loader\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.2.1-rc.2\",\n    \"@eslint/js\": \"^10.0.1\",\n    \"@types/js-yaml\": \"^4.0.9\",\n    \"@types/node\": \"^26.2.0\",\n    \"@types/react\": \"^18.3.1\",\n    \"eslint\": \"^10.11.0\",\n    \"globals\": \"^17.13.0\",\n    \"lightningcss\": \"^1.33.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^5.9.3\",\n    \"typescript-eslint\": \"^8.71.0\",\n    \"zod\": \"