      "path": "src/client/index.ts",
      "content": "/**\n * 插件管家浏览器半：挂载 dshPluginManager 远程命名空间，并向“设置→插件”注册标签页。\n *\n * 关键点：\n * - 不在 dsh.client.inject 里声明 'remote.dshPluginManager'（挂载发生在 apply 内，\n *   注入会导致自身 fiber 永久 pending）——先 $mount 再通过 ctx.remote.dshPluginManager 访问。\n * - $mount 与标签页注册都在 apply 里完成；远程调用在注入面里解包 RemoteResult。\n * @module dsh-plugin-manager/client\n */\n\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-api-remotes/client'\nimport type { RemoteResult, TypertRemoteNamespaceMap } from '@deepseek-ai/dsh-typert-protocol'\nimport type { BackupExportResult, BackupImportResult, BackupPreviewResult, CatalogEditResult, CatalogRepairResult, PluginManagerSnapshot, SetEnabledResult } from '../types.ts'\nimport { PluginManagerTab, type PluginManagerTabInjected } from './PluginManagerTab.tsx'\nimport { en, zh } from './locales.ts'\nimport { TYPERT_REMOTE } from './remote.ts'\n\nexport type { PluginManagerTabInjected, PluginManagerTabProps } from './PluginManagerTab.tsx'\n\n/** 本插件拥有的文案命名空间（带插件前缀，避免与其他作者的管理器插件撞车）。 */\nexport const NS = 'settings.dshPluginManager'\n\n/** 所需服务（cordis 注入）。 */\nexport const inject = ['slots', 'locale', 'remote']\n\n/** 挂载远程命名空间并注册设置标签页。 */\nexport async function apply(ctx: ClientContext): Promise<void> {\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-plugin-manager: dictionaries')\n\n  // 1) 挂载 dshPluginManager 命名空间（返回 disposer，随插件卸载自动清理）。\n  await ctx.effect(async () => {\n    const dispose = await ctx.remote.$mount(TYPERT_REMOTE)\n    return dispose\n  }, 'dsh-plugin-manager: remote mount')\n\n  const t = ctx.locale.bind(NS)\n\n  // 当前界面语言（评估 P2-9）：快照里的目录内容是双语的，由界面按语言取用。\n  // 非 zh 一律按英文渲染（与宿主 FALLBACK_LOCALE=en 的兜底方向一致）。\n  const localeLang = (): 'zh' | 'en' => (ctx.locale.getLocale().active.startsWith('zh') ? 'zh' : 'en')\n\n  // 2) 注入面：解包 RemoteResult，抛错给界面层处理。\n  // 不能把 remote.dshPluginManager 写进 inject（挂载发生在 apply 内，注入会让自身 fiber 永久 pending），\n  // 也不能做 ctx.remote.dshPluginManager 属性访问（cordis 要求注入）；\n  // 用免注入通道 ctx.get() 在挂载完成后取命名空间服务。\n  type PluginManagerRemote = TypertRemoteNamespaceMap['dshPluginManager']\n  const namespace = (): PluginManagerRemote => ctx.get('remote.dshPluginManager') as PluginManagerRemote\n\n  const list: PluginManagerTabInjected['list'] = async () => {\n    const result: RemoteResult<PluginManagerSnapshot> = await namespace().list()\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.list failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const setEnabled: PluginManagerTabInjected['setEnabled'] = async (entryId, enabled) => {\n    const result: RemoteResult<SetEnabledResult> = await namespace().setEnabled(entryId, enabled)\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.setEnabled failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const setOverride: PluginManagerTabInjected['setOverride'] = async (moduleName, name, desc) => {\n    const result: RemoteResult<CatalogEditResult> = await namespace().setOverride(moduleName, name, desc)\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.setOverride failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const removeOverride: PluginManagerTabInjected['removeOverride'] = async (moduleName) => {\n    const result: RemoteResult<CatalogEditResult> = await namespace().removeOverride(moduleName)\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.removeOverride failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const exportBackup: PluginManagerTabInjected['exportBackup'] = async () => {\n    const result: RemoteResult<BackupExportResult> = await namespace().exportBackup()\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.exportBackup failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const importBackup: PluginManagerTabInjected['importBackup'] = async (json, allowNonRegistrySpecs) => {\n    const result: RemoteResult<BackupImportResult> = await namespace().importBackup(json, allowNonRegistrySpecs)\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.importBackup failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const previewBackup: PluginManagerTabInjected['previewBackup'] = async (json) => {\n    const result: RemoteResult<BackupPreviewResult> = await namespace().previewBackup(json)\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.previewBackup failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const quarantineOverrides: PluginManagerTabInjected['quarantineOverrides'] = async () => {\n    const result: RemoteResult<CatalogRepairResult> = await namespace().quarantineOverrides()\n    if (!result.ok) {\n      throw new Error(`dshPluginManager.quarantineOverrides failed: ${result.error.code}: ${result.error.message}`)\n    }\n    return result.value\n  }\n  const injected = (): PluginManagerTabInjected => ({ list, setEnabled, setOverride, removeOverride, exportBackup, importBackup, previewBackup, quarantineOverrides, localeLang })\n\n  // 3) 注册标签页（排在“插件列表”之后）。\n  ctx.slots.inject('settings.plugins.tab', () => ctx.slots.register({\n    name: 'settings.plugins.tab',\n    id: 'manager',\n    order: 20,\n    label: () => t('tab'),\n    locale: NS,\n    inject: injected,\n  }, PluginManagerTab))\n}"
    },
