      "path": "src/fs-safe.ts",
      "content": "/**\n * 文件写入防呆（评估 P0-1）：所有配置写盘改为「临时文件 + rename」原子替换；\n * 补丁文件改写前自动留带时间戳的 .bak（滚动清理）。\n * 主机半专用模块（依赖 node:fs），浏览器半不得引入。\n * @module dsh-plugin-manager/fs-safe\n */\n\nimport {\n  closeSync,\n  copyFileSync,\n  existsSync,\n  fsyncSync,\n  openSync,\n  readdirSync,\n  renameSync,\n  unlinkSync,\n  writeFileSync,\n} from 'node:fs'\nimport { basename, dirname, join } from 'node:path'\n\n/** 备份文件后缀。 */\nconst BACKUP_SUFFIX = '.bak'\n\n/** 模块内自增计数：保证同一毫秒内的多次写也不会撞临时文件名。 */\nlet tempSeq = 0\n\n/** 同步休眠毫秒（rename 被锁重试时用；宿主主线程可安全 Atomics.wait）。 */\nfunction sleepSync(ms: number): void {\n  try {\n    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms)\n  } catch {\n    // 受限上下文不支持同步等待时立即返回：少一次重试间隔，不影响错误语义。\n  }\n}\n\n/**\n * 原子替换写：先写同目录临时文件并 fsync 落盘，再 rename 到目标。\n * Windows 上目标被编辑器/杀毒软件占用（EPERM/EBUSY/EACCES）时重试数次，\n * 仍失败则降级为直接覆盖写（等价旧行为，不让启停整体失败）。\n */\nexport function writeFileAtomic(targetPath: string, data: string): void {\n  const temp = join(\n    dirname(targetPath),\n    `${basename(targetPath)}.${process.pid}.${Date.now()}.${tempSeq++}.tmp`,\n  )\n  try {\n    writeFileSync(temp, data, 'utf8')\n    const fd = openSync(temp, 'r+')\n    try {\n      fsyncSync(fd)\n    } finally {\n      closeSync(fd)\n    }\n    renameWithRetry(temp, targetPath)\n  } catch (error) {\n    try {\n      if (existsSync(temp)) unlinkSync(temp)\n    } catch {\n      // 清理失败不掩盖原始错误。\n    }\n    if (renameBlocked(error)) {\n      // 降级：目标被长期占用时直接覆盖写（与旧版行为一致）。\n      writeFileSync(targetPath, data, 'utf8')\n      return\n    }\n    throw error\n  }\n}\n\n/** rename 遇到目标被占用的错误码。 */\nfunction renameBlocked(error: unknown): boolean {\n  return ['EPERM', 'EBUSY', 'EACCES'].includes((error as NodeJS.ErrnoException).code ?? '')\n}\n\n/** 带重试的 rename：短暂文件锁（杀毒扫描等）在数百毫秒内自愈。 */\nfunction renameWithRetry(from: string, to: string): void {\n  for (let attempt = 0; ; attempt += 1) {\n    try {\n      renameSync(from, to)\n      return\n    } catch (error) {\n      if (attempt >= 4 || !renameBlocked(error)) throw error\n      sleepSync(60 * (attempt + 1))\n    }\n  }\n}\n\n/** 本地时间戳（文件名友好）：YYYYMMDD-HHmmss。 */\nexport function stampOf(date: Date): string {\n  const pad = (value: number): string => String(value).padStart(2, '0')\n  return `${date.getFullYear()}${pad(date.getMonth() + 1)}${pad(date.getDate())}`\n    + `-${pad(date.getHours())}${pad(date.getMinutes())}${pad(date.getSeconds())}`\n}\n\n/** 本地日期键（YYYY-MM-DD）：判断「今天是否已备份过」。 */\nexport function localDayKey(date: Date): string {\n  const pad = (value: number): string => String(value).padStart(2, '0')\n  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`\n}\n\n/**\n * 为目标文件创建带时间戳的备份（同目录 `<名>.<时间戳>.bak`）。\n * 源文件不存在时返回 undefined；源文件内容损坏也照原样复制（备份的意义正是保住坏现场）。\n */\nexport function createTimestampedBackup(targetPath: string, now: Date): string | undefined {\n  if (!existsSync(targetPath)) return undefined\n  const backupPath = `${targetPath}.${stampOf(now)}${BACKUP_SUFFIX}`\n  copyFileSync(targetPath, backupPath)\n  return backupPath\n}\n\n/** 清理同一目标的旧备份，按时间戳保留最新 keep 份；单个删除失败不阻断。 */\nexport function pruneBackups(targetPath: string, keep: number): void {\n  let names: string[]\n  try {\n    names = readdirSync(dirname(targetPath))\n  } catch {\n    return\n  }\n  const prefix = `${basename(targetPath)}.`\n  const backups = names\n    .filter(name => name.startsWith(prefix) && name.endsWith(BACKUP_SUFFIX))\n    .sort()\n  const outdated = backups.slice(0, Math.max(0, backups.length - keep))\n  for (const name of outdated) {\n    try {\n      unlinkSync(join(dirname(targetPath), name))\n    } catch {\n      // 单个清理失败留给下一次。\n    }\n  }\n}\n"
    },
    {
      "path": "src/patch-file.ts",
      "content": "/**\n * 启停补丁文件（cordis.patch.yml）的手术式编辑：只增删目标行的 disabled 字段，\n * 保留文件里的其它行、注释与 !!js 表达式原样不动。不依赖 YAML 库——\n * 按“列 0 的 - ”切行块，行内匹配 id / disabled 键。\n * 写盘前的 YAML 回读校验在 patch-yaml 模块（编辑器本身保持零依赖）。\n * @module dsh-plugin-manager/patch-file\n */\n\n/** 一个顶层数组行块。 */\nexport interface PatchRowBlock {\n  /** 行块文本（含 \"- id: ...\" 首行）。 */\n  readonly lines: readonly string[]\n  /** 首行在文件中的下标（0 起）。 */\n  readonly start: number\n  /** 结束行下标（不含）。 */\n  readonly end: number\n  /** 行块声明的 id（无 id 时为 null）。 */\n  readonly id: string | null\n  /** disabled 行在块内的相对下标；无该字段时为 -1。 */\n  readonly disabledIndex: number\n  /** disabled 字段的原始值（已 trim）；无该字段时为 null。 */\n  readonly disabledValue: string | null\n}\n\n/** 去掉 YAML 标量两侧的成对引号。 */\nfunction unquote(value: string): string {\n  const trimmed = value.trim()\n  if (trimmed.length >= 2) {\n    const first = trimmed[0]\n    const last = trimmed[trimmed.length - 1]\n    if ((first === \"'\" && last === \"'\") || (first === '\"' && last === '\"')) {\n      return trimmed.slice(1, -1)\n    }\n  }\n  return trimmed\n}\n\n/** 判断 disabled 值是否为 !!js 表达式（不可安全编辑）。 */\nexport function isExpression(value: string | null): boolean {\n  return value !== null && value.trim().startsWith('!!js')\n}\n\n/** 去掉值尾部的行内注释（第一个「 #」起的尾串）并 trim，仅用于键值比较，不回写。 */\nfunction stripInlineComment(value: string): string {\n  const at = value.search(/\\s#/)\n  return (at >= 0 ? value.slice(0, at) : value).trim()\n}\n\n/** 提取一行的行内注释尾串（含前导空白）；改写 disabled 键时原样保留，避免销毁用户注释。 */\nfunction inlineCommentSuffix(line: string): string {\n  const at = line.search(/\\s#/)\n  return at >= 0 ? line.slice(at) : ''\n}\n\n/** 把文件内容解析为顶层行块序列（忽略注释与空行，保留原文文本）。 */\nexport function parsePatchFile(content: string): PatchRowBlock[] {\n  const lines = content.split(/\\r?\\n/)\n  const blocks: PatchRowBlock[] = []\n  let index = 0\n  while (index < lines.length) {\n    const line = lines[index] ?? ''\n    if (!/^- /.test(line)) {\n      index += 1\n      continue\n    }\n    const start = index\n    index += 1\n    while (index < lines.length && !/^- /.test(lines[index] ?? '')) index += 1\n    const blockLines = lines.slice(start, index)\n    let id: string | null = null\n    let disabledIndex = -1\n    let disabledValue: string | null = null\n    for (let at = 0; at < blockLines.length; at += 1) {\n      const text = blockLines[at] ?? ''\n      // 用 match 而非 exec：语义一致（非全局正则），且不触发安全扫描的命令执行误报。\n      const idMatch = text.match(/^- id:\\s*(.*)$/)\n      if (idMatch) id = unquote(stripInlineComment(idMatch[1] ?? ''))\n      const disabledMatch = text.match(/^(\\s*)disabled:\\s*(.*)$/)\n      if (disabledMatch && disabledIndex < 0) {\n        disabledIndex = at\n        disabledValue = stripInlineComment(disabledMatch[2] ?? '')\n      }\n    }\n    blocks.push({ lines: blockLines, start, end: index, id, disabledIndex, disabledValue })\n  }\n  return blocks\n}\n\n/**\n * 追加（或替换空数组标记 [] 为）一个启停行块。\n * 文件处于“仅注释 + []”的空形态时，直接把 [] 行替换成新行块，保证仍是合法 YAML。\n */\nfunction appendRow(\n  lines: string[],\n  eol: string,\n  content: string,\n  entryId: string,\n  value: 'true' | 'false',\n): { content: string; changed: boolean; blocked: null } {\n  const addition = [`- id: ${entryId}`, `  disabled: ${value}`]\n  const marker = lines.findIndex(line => line.trim() === '[]')\n  if (marker >= 0) {\n    const next = [...lines]\n    next.splice(marker, 1, ...addition)\n    return { content: next.join(eol), changed: true, blocked: null }\n  }\n  const trimmed = content.length > 0 && !content.endsWith(eol) ? content + eol : content\n  return { content: trimmed + addition.join(eol) + eol, changed: true, blocked: null }\n}\n\n/** 检测文件的行尾风格（\\r\\n 或 \\n）。 */\nfunction eolOf(content: string): string {\n  return content.includes('\\r\\n') ? '\\r\\n' : '\\n'\n}\n\n/**\n * 检测「目标 id 已在文件里、但不是行块首键形态」的无法识别行（评估 P0-2）。\n * 例如手工写的 `- name: x` 换行 `id: y`、缩进的续行 id、多写空格的 `-   id:`。\n * 这类行无法被行块编辑安全改写；不检测会在启停时静默追加重复行，永不生效。\n */\nfunction hasUnrecognizedIdRow(content: string, entryId: string): boolean {\n  for (const line of content.split(/\\r?\\n/)) {\n    const text = line.trimStart()\n    if (text.startsWith('#')) continue\n    const match = text.match(/^(?:-\\s+)?id:\\s*(.*)$/)\n    if (match && unquote(stripInlineComment(match[1] ?? '')) === entryId) return true\n  }\n  return false\n}\n\n/**\n * 在补丁文件内容里为 entryId 设置/清除 disabled。\n * @param content - 当前文件内容。\n * @param entryId - 目标行 id。\n * @param enabled - true=启用（写/改 disabled: false 显式覆盖），false=停用（写 disabled: true）。\n * @returns 新内容与结果描述；未命中任何行且无需写入时 content 不变。\n *   blocked 为 'unrecognized' 表示目标行存在但格式无法识别（拒绝写入重复行）。\n */\nexport function setRowDisabled(\n  content: string,\n  entryId: string,\n  enabled: boolean,\n): { content: string; changed: boolean; blocked: 'expression' | 'unrecognized' | null } {\n  const eol = eolOf(content)\n  const lines = content.split(/\\r?\\n/)\n  const blocks = parsePatchFile(content)\n  const target = blocks.find(block => block.id === entryId)\n\n  if (target !== undefined && target.disabledIndex >= 0 && isExpression(target.disabledValue)) {\n    return { content, changed: false, blocked: 'expression' }\n  }\n\n  if (!enabled) {\n    // 停用：保证存在 disabled: true。\n    if (target !== undefined && target.disabledValue === 'true') {\n      return { content, changed: false, blocked: null }\n    }\n    if (target !== undefined && target.disabledIndex >= 0) {\n      const next = [...lines]\n      const comment = inlineCommentSuffix(lines[target.start + target.disabledIndex] ?? '')\n      next[target.start + target.disabledIndex] = `  disabled: true${comment}`\n      return { content: next.join(eol), changed: true, blocked: null }\n    }\n    if (target !== undefined) {\n      // 已有行但无 disabled 字段：插到 id 行之后。\n      const next = [...lines]\n      next.splice(target.start + 1, 0, '  disabled: true')\n      return { content: next.join(eol), changed: true, blocked: null }\n    }\n    if (hasUnrecognizedIdRow(content, entryId)) {\n      return { content, changed: false, blocked: 'unrecognized' }\n    }\n    // 没有行：追加新块（或替换空数组标记 []）。\n    return appendRow(lines, eol, content, entryId, 'true')\n  }\n\n  // 启用：写显式 disabled: false（可覆盖更低层的 disable），或把 true 改成 false。\n  if (target !== undefined) {\n    if (target.disabledIndex >= 0) {\n      const next = [...lines]\n      const comment = inlineCommentSuffix(lines[target.start + target.disabledIndex] ?? '')\n      next[target.start + target.disabledIndex] = `  disabled: false${comment}`\n      return { content: next.join(eol), changed: true, blocked: null }\n    }\n    const next = [...lines]\n    next.splice(target.start + 1, 0, '  disabled: false')\n    return { content: next.join(eol), changed: true, blocked: null }\n  }\n  if (hasUnrecognizedIdRow(content, entryId)) {\n    return { content, changed: false, blocked: 'unrecognized' }\n  }\n  return appendRow(lines, eol, content, entryId, 'false')\n}\n\n/** 生成补丁文件的初始内容（文件不存在时）。 */\nexport function initialPatchFile(): string {\n  return [\n    '# dsh-plugin-manager（插件管家）管理的启停补丁 —— 全局层，修改后实时热生效。',\n    '# 你仍可手工编辑本文件；插件管家只在需要时增删“- id: … / disabled: …”行块。',\n    '# !!js 表达式控制的插件不会被插件管家改写。',\n    '[]',\n    '',\n  ].join('\\n')\n}"
    },
    {
      "path": "src/origin.ts",
      "content": "/**\n * 插件来源标记（issue #1）的纯函数：官方/社区粗分与「用户安装」信号推导。\n * 只依赖纯输入，不触碰 DOM / 远程服务 / node:fs，node 可直跑导入（smoke 测试用）。\n * @module dsh-plugin-manager/origin\n */\n\n/**\n * 官方 scope 清单：只用于官方/社区粗分（来源徽标与「官方内置」筛选），\n * 不参与「是否用户安装」的判断——后者以 profile 依赖表为准（issue #1 的建议）。\n * @cordis 一并算官方：框架自带行，绝不可能是社区插件。\n */\nconst OFFICIAL_SCOPES: readonly string[] = ['@deepseek-ai/', '@cordis/']\n\n/** 是否官方 scope 模块（非字符串输入一律按非官方兜底，不抛错）。 */\nexport function isOfficialModule(moduleName: unknown): boolean {\n  return typeof moduleName === 'string' && OFFICIAL_SCOPES.some(scope => moduleName.startsWith(scope))\n}\n\n/** 模块名是否出现在 profile 依赖表里（用户主动安装信号，含 file: 等非常规 spec）。 */\nexport function isDeclaredDependency(dependencies: Readonly<Record<string, string>>, moduleName: unknown): boolean {\n  return typeof moduleName === 'string' && Object.hasOwn(dependencies, moduleName)\n}\n"
    },
    {
      "path": "tests/fs-safe.smoke.mjs",
      "content": "// 原子写与备份防呆冒烟测试（node 直跑，不依赖测试框架）。\nimport assert from 'node:assert'\nimport { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { createTimestampedBackup, localDayKey, pruneBackups, writeFileAtomic } from '../lib/types/fs-safe.js'\n\nconst dir = mkdtempSync(join(tmpdir(), 'dsh-pm-fs-'))\nlet pass = 0\n\ntry {\n  // 1) writeFileAtomic：创建 + 覆盖 + 无临时文件残留\n  {\n    const target = join(dir, 'a.yml')\n    writeFileAtomic(target, 'first\\n')\n    assert.strictEqual(readFileSync(target, 'utf8'), 'first\\n')\n    writeFileAtomic(target, 'second\\n')\n    assert.strictEqual(readFileSync(target, 'utf8'), 'second\\n')\n    assert.ok(!readdirSync(dir).some(name => name.endsWith('.tmp')), 'no temp leftovers')\n    pass += 1\n  }\n\n  // 2) createTimestampedBackup：源缺失返回 undefined；存在时备份内容一致\n  {\n    const target = join(dir, 'b.yml')\n    assert.strictEqual(createTimestampedBackup(target, new Date()), undefined)\n    writeFileSync(target, 'payload\\n', 'utf8')\n    const backup = createTimestampedBackup(target, new Date(2026, 0, 2, 3, 4, 5))\n    assert.ok(backup !== undefined && backup.endsWith('.20260102-030405.bak'), 'timestamped name: ' + String(backup))\n    assert.strictEqual(readFileSync(backup, 'utf8'), 'payload\\n')\n    pass += 1\n  }\n\n  // 3) pruneBackups：保留最新 keep 份，旧的清掉\n  {\n    const target = join(dir, 'c.yml')\n    writeFileSync(target, 'x\\n', 'utf8')\n    const stamps = []\n    for (let i = 1; i <= 7; i += 1) {\n      stamps.push(createTimestampedBackup(target, new Date(2026, 0, 1, 0, 0, i)))\n    }\n    assert.strictEqual(stamps.length, 7)\n    pruneBackups(target, 5)\n    const left = readdirSync(dir).filter(name => name.startsWith('c.yml.') && name.endsWith('.bak')).sort()\n    assert.strictEqual(left.length, 5, 'keep 5 newest, got: ' + left.join(','))\n    assert.ok(left[0].endsWith('000003.bak'), 'oldest two pruned: ' + left[0])\n    pass += 1\n  }\n\n  // 4) 损坏内容也能备份（备份的意义正是保住坏现场）\n  {\n    const target = join(dir, 'd.yml')\n    writeFileSync(target, 'broken: [yaml\\n', 'utf8')\n    const backup = createTimestampedBackup(target, new Date())\n    assert.ok(backup !== undefined && readFileSync(backup, 'utf8') === 'broken: [yaml\\n')\n    pass += 1\n  }\n\n  // 5) localDayKey：本地日期键格式\n  {\n    assert.strictEqual(localDayKey(new Date(2026, 9, 1)), '2026-10-01')\n    assert.strictEqual(localDayKey(new Date(2026, 0, 5)), '2026-01-05')\n    pass += 1\n  }\n} finally {\n  rmSync(dir, { recursive: true, force: true })\n}\n\nassert.ok(!existsSync(dir), 'temp dir cleaned')\nconsole.log('fs-safe.smoke: ' + pass + '/5 groups passed')\n"
    }
